command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="eccc723ce730b49be79626cf2e5794d1e2a9fabc"
$baselineProduct="4e59a22c742c7fa8d5d0e21e221f01ff8151e2be"
Set-Location -LiteralPath $repo
& git fetch origin main --no-tags
if($LASTEXITCODE -ne 0){throw "baseline diagnostic fetch failed"}
$originMain=(& git rev-parse refs/remotes/origin/main).Trim()
Write-Host ("ORIGIN_MAIN="+$originMain)
& git diff --quiet ($baselineProduct+".."+$main) -- app/winui src/base build.bat run.bat
Write-Host ("BASELINE_PRODUCT_EQUIVALENT="+($LASTEXITCODE -eq 0))
$root="C:\dev\flyExplorer\logs"
if(Test-Path -LiteralPath $root){
  Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -match "runtime|f5|f6|outbound|transfer" } |
    ForEach-Object {
      $exe=Join-Path $_.FullName "flyExplorer.exe"
      Write-Host ("CACHE "+$_.FullName+" EXE="+(Test-Path -LiteralPath $exe))
    }
}else{
  Write-Host "CACHE_ROOT_MISSING"
}
